### 5. **Mirror List Output Table Format**

The `entire repo mirror list` command uses a reusable table rendering system.

#### Table Columns and Row Formatting

**File:** `/Users/paul/.claude/worktrees/cli/mutable-spinning-umbrella/cmd/entire/cli/repo_mirror.go:26-36`
```go
// mirrorColumns is the human table/field view of a mirror: the scannable
// repo name, the clone URL you'd copy, and whether the upstream is
// private. The cluster is omitted — it's already embedded in the clone
// URL — and the wire model's internal ids are dropped entirely. The clone
// URL is synthesised from the mirror's coords (the form `git clone`
// accepts), since the list API doesn't return it.
var mirrorColumns = []string{"REPO", "CLONE URL", "PRIVATE"}

func mirrorRow(m coreapi.Mirror) []string {
	repo := m.Owner + "/" + m.Repo
	cloneURL := fmt.Sprintf("entire://%s/gh/%s/%s", m.ClusterHost, m.Owner, m.Repo)
	private := "no"
	if m.IsPrivate.Or(false) {
		private = "yes"
	}
	return []string{repo, cloneURL, private}
}
```

#### List Command Implementation

**File:** `/Users/paul/.claude/worktrees/cli/mutable-spinning-umbrella/cmd/entire/cli/repo_mirror.go:248-313`
```go
func newRepoMirrorListCmd() *cobra.Command {
	var cluster, provider, owner string
	var showAvailable bool
	cmd := &cobra.Command{
		Use:   "list",
		Short: "List mirrors you can see (or, with --show-available, repos you could mirror)",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if showAvailable {
				return runCoreList(cmd, availableMirrorColumns, availableMirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.AvailableMirror, error) {
					if !jsonRequested(cmd) {
						fmt.Fprintf(cmd.ErrOrStderr(), "Listing repos you could mirror, via %s\n", c.CoreOrigin())
					}
					var params coreapi.ListAvailableMirrorsParams
					if owner != "" {
						params.Owner = coreapi.NewOptString(owner)
					}
					out, err := c.ListAvailableMirrors(ctx, params)
					if err != nil {
						return nil, err
					}
					return out.Available, nil
				})
			}
			return runCoreList(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.Mirror, error) {
				if !jsonRequested(cmd) {
					fmt.Fprintf(cmd.ErrOrStderr(), "Listing mirrors on %s\n", c.CoreOrigin())
				}
				var params coreapi.ListMirrorsParams
				if cluster != "" {
					params.Cluster = coreapi.NewOptString(cluster)
				}
				if provider != "" {
					params.Provider = coreapi.NewOptString(provider)
				}
				if owner != "" {
					params.Owner = coreapi.NewOptString(owner)
				}
				out, err := c.ListMirrors(ctx, params)
				if err != nil {
					return nil, err
				}
				return out.Mirrors, nil
			})
		},
	}
	// ... flags ...
	return cmd
}
```

#### Table Rendering Infrastructure

**File:** `/Users/paul/.claude/worktrees/cli/mutable-spinning-umbrella/cmd/entire/cli/corecmd.go:48-83`
```go
// runCoreList fetches a slice via fn and renders it as an aligned table
// (default) or the raw wire JSON (--json). headers names the columns; row
// maps one item to its cells in the same order.
func runCoreList[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) error {
	return runCore(cmd, renderCoreList(cmd, headers, row, fn))
}

// renderCoreList builds the run-function shared by runCoreList and
// runCoreListForCluster: fetch via fn, then render as a table (default) or raw
// JSON (--json). Kept separate from the client-selection so the two list
// variants differ only in which core they dial.
func renderCoreList[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) func(context.Context, *coreapi.Client) error {
	return func(ctx context.Context, c *coreapi.Client) error {
		items, err := fn(ctx, c)
		if err != nil {
			return err
		}
		if jsonRequested(cmd) {
			return printJSON(cmd.OutOrStdout(), items)
		}
		if len(items) == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "(none)")
			return nil
		}
		return printTable(cmd.OutOrStdout(), headers, items, row)
	}
}
```

**File:** `/Users/paul/.claude/worktrees/cli/mutable-spinning-umbrella/cmd/entire/cli/corecmd.go:146-163`
```go
// printTable writes headers plus one row per item, columns aligned on the
// plain-text widths so ANSI color codes don't throw off the layout (they're
// applied after padding). Callers handle the empty case.
func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
	st := newTableStyles(w)
	rows := make([][]string, len(items))
	for i, it := range items {
		rows[i] = row(it)
	}
	widths := columnWidths(headers, rows)

	var b strings.Builder
	writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
	for _, r := range rows {
		writeTableRow(&b, r, widths, st.columnStyle, st)
	}
	if _, err := io.WriteString(w, b.String()); err != nil {
		return fmt.Errorf("render table: %w", err)
	}
	return nil
}
```

